global.measureRows=async(id,name)=>{const rows=await p.locator(id+' tr').evaluateAll(es=>es.map(e=>({height:e.getBoundingClientRect().height,text:e.innerText,top:e.getBoundingClientRect().top})));log('row-density',{name,viewport:await p.viewportSize(),rows,previewHeights});return rows};
